// Synthetic preview only. Production screens are generated by the C++ terminal.
import data from './ui-data.js';

// The double-line frame the firmware draws (CP437 201 205 187 186 200 188 204 185) and the
// single line (196) beside the model name on the main menu.
const TL = '\u2554', TR = '\u2557', BL = '\u255a', BR = '\u255d';
const H = '\u2550', V = '\u2551', TEE_L = '\u2560', TEE_R = '\u2563', THIN = '\u2500';

const ESC = '\x1b[';
const palette = data.colors;
const ink = {
    body: palette.primary_text, frame: palette.frame_white, logo: palette.logo_red,
    title: palette.bright_cyan, key: palette.hotkey_green, hint: palette.shortcut_blue,
    muted: palette.muted_text, disabled: palette.disabled_gray,
};

export function startDemoModem({message, write}) {
    let cols = 80, rows = 25, screen = null, selected = 0, model = data.models[1];
    let detail = null, confirm = false, swallowEnter = false, escape = '', skipLf = false;
    let feedback = 'DEMO - synthetic preview; no device services connected.';
    let call = {t: 'call', state: 'idle'};
    const stack = [];
    const redraw = () => {
        const cells = Array.from({length: rows}, () => Array.from({length: cols}, () => ({c: ' ', color: ink.body})));
        const put = (x, y, text, color = ink.body, max = cols - x - 1) => {
            if (y < 0 || y >= rows) return;
            for (const c of Array.from(text).slice(0, max)) {
                if (x >= 0 && x < cols) cells[y][x] = {c, color};
                x++;
            }
        };
        const center = (y, text, color) => put(Math.floor((cols - text.length) / 2), y, text, color);
        const box = (x, y, w, h) => {
            put(x, y, TL + H.repeat(w - 2) + TR, ink.frame, w);
            put(x, y + h - 1, BL + H.repeat(w - 2) + BR, ink.frame, w);
            for (let r = y + 1; r < y + h - 1; r++) { put(x, r, V, ink.frame); put(x + w - 1, r, V, ink.frame); }
        };
        const rule = y => put(0, y, TEE_L + H.repeat(cols - 2) + TEE_R, ink.frame, cols);
        box(0, 0, cols, rows);
        const main = !screen && !detail && !confirm;
        const wide = cols >= 120 && rows >= 45;
        if (main) {
            data.logo.forEach((line, r) => put(Math.floor((cols - 59) / 2), r + 1, line, ink.logo));
            center(6, `${THIN.repeat(3)} ${model.label} ${THIN.repeat(3)}`, model.accent);
            rule(7); center(7, '[ MODEM CONFIGURATION - MAIN MENU ]', ink.title);
        } else {
            put(3, 1, 'USRobotics', ink.logo); put(23, 1, model.label, model.accent);
            rule(2); center(2, `[ MAIN > ${screen?.label || 'HELP'} ]`, ink.title);
        }
        if (confirm) {
            put(3, 5, 'DEMO: simulate a call to demo.invalid?', ink.title);
            put(3, 7, 'Y confirms; N or Esc cancels. No network connection is made.');
        } else if (detail) {
            const lines = detail.split('\n');
            lines.slice(0, rows - 10).forEach((line, n) => put(3, n + 5, line));
        } else if (!screen) {
            const divider = Math.floor(cols / 2) - 1;
            data.menu.forEach((item, i) => {
                let x = i < 6 ? 2 : divider + 2, y = 8 + (i < 6 ? i : i - 6);
                if (wide) { y = 11 + 4 * (i < 6 ? i : i - 6); box(x, y, divider - 2, 4); x += 2; y++; }
                const color = item.status === 'unavailable' ? ink.disabled : ink.title;
                put(x, y, `${i === selected ? '>' : ' '} [${item.key}] ${item.label}${item.status === 'unavailable' ? ' [X]' : ''}`, color, divider - 3);
                put(x + 3, y, item.key, item.status === 'unavailable' ? ink.disabled : ink.key, 1);
                if (wide) put(x + 1, y + 1, item.summary, ink.body, divider - 7);
            });
            if (wide) {
                put(3, 36, 'ARROWS Navigate  ENTER Select  Q Quit', ink.body, divider - 4);
                put(3, 37, '[C] Client Tests - serial only', ink.disabled, divider - 4);
            } else {
                rule(rows - 9);
                put(3, rows - 8, 'ARROWS Navigate  ENTER Select  Q Quit');
                put(3, rows - 7, '[C] Client Tests - serial only', ink.disabled);
            }
        } else if (screen.id === 'phonebook') {
            put(3, 4, 'PHONEBOOK ENTRIES - DEMO fixture', ink.title);
            put(3, 6, '> 1  demo.invalid (DEMO)          200       28800');
            put(3, 16, 'Host: demo.invalid  Number: 200  Configured speed: 28800');
            put(3, 17, '[I] Details | [1] List | [2] Add / edit', ink.key);
            put(3, 18, '[3] Delete | [4] Dial (DEMO simulation)', ink.key);
        } else {
            screen.items.forEach((item, i) => put(3, 5 + i, `${i === selected ? '>' : ' '} [${item.key}] ${item.label}`));
        }
        rule(rows - 6);
        put(3, rows - 5, main ? 'F1 Help  F2 Status  F3 Phonebook  F4 Settings  F10 Exit' : 'ESC/Q Back  F1 Help  F2 Main  H End simulated call', ink.hint);
        put(3, rows - 4, `Model: ${model.short_label} | Profile: DEMO | Link: ${call.state.toUpperCase()}`);
        put(3, rows - 3, feedback, ink.muted);
        put(3, rows - 2, 'Command >');
        let out = `${ESC}?25l${ESC}?7l${ESC}0m${ESC}48;2;3;5;7m${ESC}2J`;
        cells.forEach((row, y) => {
            out += `${ESC}${y + 1};1H`;
            let color = '';
            for (const cell of row) {
                if (cell.color !== color) {
                    color = cell.color;
                    const n = parseInt(color.slice(1), 16);
                    out += `${ESC}38;2;${n >> 16};${(n >> 8) & 255};${n & 255}m`;
                }
                out += cell.c;
            }
        });
        write(out + `${ESC}0m${ESC}${rows - 1};14H${ESC}?7h${ESC}?25h`);
    };
    const back = () => {
        if (detail || confirm) { detail = null; confirm = false; }
        else if (stack.length) { const previous = stack.pop(); screen = previous.screen; selected = previous.selected; }
        else { screen = null; feedback = 'DEMO - preview remains open; no modem session to release.'; }
        redraw();
    };
    const open = item => {
        if (item.status === 'unavailable') feedback = 'Not available';
        else if (!screen) {
            stack.push({screen, selected}); screen = item; selected = 0;
            if (!item.items.length) detail = `DEMO: ${item.label}\nNo device service connected.\nThis read-only preview does not run modem commands.`;
        } else if (screen.id === 'phonebook' && item.key === '1') detail = null;
        else if (screen.id === 'phonebook' && item.key === '4') confirm = true;
        else if (item.id === 'settings.model') detail = 'DEMO model selector\n1 14.4k    2 28.8k    3 33.6k    4 56k\nChanges this preview only.';
        else if (screen.id === 'client-tests') detail = 'Client Tests run on the USB console or RS232 port.\nThe browser lists them but cannot run them.';
        else detail = `DEMO: ${item.label}\nAction unavailable in the preview.\nThe real modem uses its existing service.`;
        redraw();
    };
    const key = ch => {
        if (ch === '\n' && swallowEnter) return;
        if ((ch === '\r' || ch === '\n') && swallowEnter) { swallowEnter = false; return; }
        if (ch === 'HELP') { detail = 'DEMO help\nArrows select; Enter opens; menu hotkeys open immediately.\nEsc/Q Back; F2 Main. C lists serial-only Client Tests.\nPhonebook 4 simulates a call after confirmation; H ends it.\nAll device values and contacts in this preview are synthetic.'; redraw(); return; }
        if (ch === '\x1b' || ch.toUpperCase() === 'Q' || ch === 'EXIT') { back(); return; }
        if (ch === 'MAIN') { screen = null; detail = null; confirm = false; stack.length = 0; selected = 0; redraw(); return; }
        if (confirm) {
            if (ch.toUpperCase() === 'Y') {
                confirm = false;
                call = {t: 'call', state: 'connected', host: 'demo.invalid', number: '200', port: 23, speed: 28800, mode: 'telnet', dir: 'out', since: 0};
                message(call); message({t: 'led', m: 2}); feedback = 'DEMO simulated call. H ends it; no network connection.';
            } else if (ch.toUpperCase() === 'N') confirm = false;
            swallowEnter = true; redraw(); return;
        }
        if (detail) {
            if (screen?.id === 'settings' && detail.startsWith('DEMO model selector') && /^[1-4]$/.test(ch)) {
                model = data.models[Number(ch) - 1]; detail = null; swallowEnter = true; redraw();
            } else if (ch === '\r' || ch === '\n') back();
            return;
        }
        if (ch.toUpperCase() === 'H') { call = {t: 'call', state: 'idle'}; message(call); message({t: 'led', m: 0}); feedback = 'DEMO - simulated call ended.'; redraw(); return; }
        const items = screen ? screen.items : data.menu;
        if (ch === 'UP' || ch === 'DOWN') {
            do selected = (selected + (ch === 'UP' ? -1 : 1) + items.length) % items.length;
            while (items[selected]?.status === 'unavailable');
        } else if (!screen && ch === 'RIGHT' && selected < 6) selected += 6;
        else if (!screen && ch === 'LEFT' && selected >= 6) selected = Math.min(5, selected - 6);
        else if (screen?.id === 'phonebook' && ch.toUpperCase() === 'I') detail = 'DEMO fixture\nHost: demo.invalid\nNumber: 200\nPort: 23\nProtocol: TELNET\nConfigured speed: 28800';
        else if (ch === '\r' || ch === '\n') open(items[selected]);
        else {
            const index = items.findIndex(i => i.key === ch.toUpperCase());
            if (index >= 0) { if (items[index].status !== 'unavailable') selected = index; open(items[index]); swallowEnter = true; }
        }
        redraw();
    };
    message({t: 'hello', name: 'Sportster DEMO', ver: 'DEMO', size: true});
    message({t: 'clock', epoch: 0, tzo: 0});
    message({t: 'wifi', state: 'down'}); message({t: 'led', m: 0}); message(call);
    redraw();
    return {
        receive(bytes) {
            if (typeof bytes === 'string') {
                const value = JSON.parse(bytes);
                if (value.t === 'size' && Number.isInteger(value.cols) && Number.isInteger(value.rows) && value.cols >= 80 && value.cols <= 132 && value.rows >= 25 && value.rows <= 50) { cols = value.cols; rows = value.rows; redraw(); }
                return;
            }
            for (const ch of new TextDecoder().decode(bytes)) {
                if (ch === '\n' && skipLf) { skipLf = false; continue; }
                skipLf = ch === '\r';
                if (escape) {
                    escape += ch;
                    const special = {'\x1b[A': 'UP', '\x1b[B': 'DOWN', '\x1b[C': 'RIGHT', '\x1b[D': 'LEFT', '\x1bOP': 'HELP', '\x1bOQ': screen ? 'MAIN' : '1', '\x1bOR': '2', '\x1bOS': '3', '\x1b[21~': 'EXIT'}[escape];
                    if (special) { escape = ''; key(special); }
                    else if (escape.length > 8 || (escape.length > 2 && /[A-Za-z~]$/.test(escape))) escape = '';
                    else if (escape.length === 2 && !['[', 'O'].includes(ch)) { escape = ''; key('\x1b'); key(ch); }
                } else if (ch === '\x1b') { escape = ch; queueMicrotask(() => { if (escape === '\x1b') { escape = ''; key('\x1b'); } }); }
                else key(ch);
            }
        },
    };
}
